import java.util.*;

public class Test {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        String str = in.next();
        str += "^";
        n++;

        char[] copy = new char[256];
        for (int i = 0; i < n; i++) copy[i] = str.charAt(i);
        StringBuilder buf = n > 0 ? new StringBuilder(new String(copy, 0, n)) : new StringBuilder();

        Deque<String> outside = new ArrayDeque<>();
        Deque<String> inside = new ArrayDeque<>();
        int flag = 0;
        StringBuilder s = new StringBuilder();

        for (int i = 0; i < n; i++) {
            char c = buf.charAt(i);
            if (c == '(') {
                flag = 1;
                buf.setCharAt(i, '^');
                continue;
            } else if (c == ')') {
                flag = 0;
                inside.addLast(s.toString());
                buf.setCharAt(i, '^');
                s.setLength(0);
            }
            if (flag == 1) {
                s.append(buf.charAt(i));
                buf.setCharAt(i, '^');
            }
        }

        s.setLength(0);
        for (int i = 0; i < n; i++) {
            if (buf.charAt(i) == '^') {
                if (s.length() > 0) {
                    outside.addLast(s.toString());
                    s.setLength(0);
                }
            } else {
                s.append(buf.charAt(i));
            }
        }

        int max = 0;
        for (String part : outside) {
            String t = part + "_";
            int current = 0;
            for (int i = 0; i < t.length(); i++) {
                char c = t.charAt(i);
                if (Character.isLetter(c)) current++;
                else if (c == '_') {
                    if (current > max) max = current;
                    current = 0;
                }
            }
        }

        int count = 0;
        for (String part : inside) {
            String t = part + "_";
            StringBuilder word = new StringBuilder();
            for (int i = 0; i < t.length(); i++) {
                char c = t.charAt(i);
                if (Character.isLetter(c)) word.append(c);
                else if (c == '_' && word.length() > 0) {
                    word.setLength(0);
                    count++;
                }
            }
        }

        System.out.println(max + " " + count);
    }
}
